import{bV as e,aL as l,u as t,G as i}from"./chunks/framework.CzwWnRE6.js";const y=JSON.parse('{"title":"MySQL 教程","description":"","frontmatter":{"title":"MySQL 教程","date":"2026/04/03 16:10:35","permalink":"/mysql/","sidebarSort":1,"categories":["mysql"]},"headers":[],"relativePath":"mysql/README.md","filePath":"mysql/README.md","lastUpdated":null}'),r={name:"mysql/README.md"};function s(o,a,n,d,m,p){return l(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="mysql-教程" tabindex="-1">MySQL 教程 <a class="header-anchor" href="#mysql-教程" aria-label="Permalink to &quot;MySQL 教程&quot;">​</a></h1><p>MySQL 是最流行的关系型数据库管理系统，在 WEB 应用方面 MySQL 是最好的 RDBMS(Relational Database Management System：关系数据库管理系统)应用软件之一。</p><h2 id="什么是数据库" tabindex="-1">什么是数据库？ <a class="header-anchor" href="#什么是数据库" aria-label="Permalink to &quot;什么是数据库？&quot;">​</a></h2><p>数据库（Database）是按照数据结构来组织、存储和管理数据的仓库。</p><p>每个数据库都有一个或多个不同的 API 用于创建，访问，管理，搜索和复制所保存的数据。</p><p>我们也可以将数据存储在文件中，但是在文件中读写数据速度相对较慢。</p><p>所以，现在我们使用关系型数据库管理系统（RDBMS）来存储和管理大数据量。所谓的关系型数据库，是建立在关系模型基础上的数据库，借助于集合代数等数学概念和方法来处理数据库中的数据。</p><p>RDBMS 即关系数据库管理系统(Relational Database Management System)的特点：</p><p>1.数据以表格的形式出现2.每行为各种记录名称3.每列为记录名称所对应的数据域4.许多的行和列组成一张表单5.若干的表单组成database</p><h2 id="rdbms-术语" tabindex="-1">RDBMS 术语 <a class="header-anchor" href="#rdbms-术语" aria-label="Permalink to &quot;RDBMS 术语&quot;">​</a></h2><ol><li>数据库（Database）：数据库是一些关联表的集合。</li><li>表（Table）：表是数据的矩阵。在一个数据库中的表看起来像一个简单的电子表格。</li><li>列（Column）：一列(数据元素) 包含了相同类型的数据, 例如邮政编码的数据。</li><li>行（Row）：一行(数据元素) 包含了相同类型的数据, 例如姓名的数据。</li><li>冗余（Redundancy）：存储两倍数据，冗余降低了性能，但提高了数据的安全性。</li><li>主键（Primary Key）：主键是表中唯一标识一行的列。</li><li>外键（Foreign Key）：外键是表中用于关联两个表的列。</li><li>复合键（Composite Key）：复合键（组合键）将多个列作为一个索引键，一般用于复合索引。</li><li>索引（Index）：使用索引可快速访问数据库表中的特定信息。索引是对数据库表中一列或多列的值进行排序的一种结构。类似于书籍的目录。</li></ol>',11)])])}const _=e(r,[["render",s]]);export{y as __pageData,_ as default};
